<?php
require dirname(__DIR__).'/app/bootstrap.php';
require_permission('settings.manage');
$pdo->exec("CREATE TABLE IF NOT EXISTS analytics_daily (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, day DATE NOT NULL, page_type VARCHAR(20) NOT NULL DEFAULT 'page', post_id INT UNSIGNED NULL, views INT UNSIGNED NOT NULL DEFAULT 0, UNIQUE KEY uq_analytics_day_type_post(day,page_type,post_id), INDEX idx_analytics_day(day), INDEX idx_analytics_post(post_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$days=max(7,min(90,(int)($_GET['days']??30)));
$q=$pdo->prepare("SELECT day,SUM(views) views,SUM(CASE WHEN page_type='article' THEN views ELSE 0 END) article_views,SUM(CASE WHEN page_type='page' THEN views ELSE 0 END) page_views FROM analytics_daily WHERE day>=DATE_SUB(CURDATE(),INTERVAL ? DAY) GROUP BY day ORDER BY day");
$q->execute([$days]); $rows=$q->fetchAll();
$total=(int)$pdo->query("SELECT COALESCE(SUM(views),0) FROM analytics_daily WHERE day>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
$articles=(int)$pdo->query("SELECT COALESCE(SUM(views),0) FROM analytics_daily WHERE page_type='article' AND day>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
$popular=$pdo->query("SELECT p.id,p.title,p.slug,COALESCE(SUM(a.views),0) views FROM posts p LEFT JOIN analytics_daily a ON a.post_id=p.id AND a.page_type='article' AND a.day>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) WHERE p.status='published' GROUP BY p.id,p.title,p.slug ORDER BY views DESC,p.published_at DESC LIMIT 10")->fetchAll();
$max=1; foreach($rows as $r) $max=max($max,(int)$r['views']);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Analytics — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.analytics-wrap{max-width:1100px;margin:36px auto;padding:0 24px}.analytics-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.analytics-card,.analytics-panel{border:1px solid var(--line);border-radius:16px;background:var(--panel,#fff);padding:20px}.analytics-card small{color:var(--muted)}.analytics-card strong{display:block;font-size:32px;margin:8px 0}.analytics-chart{display:flex;align-items:end;gap:5px;height:150px;margin-top:20px}.analytics-bar{flex:1;min-width:3px;background:var(--accent,#c6f36b);border-radius:5px 5px 0 0;position:relative}.analytics-bar span{position:absolute;bottom:-24px;left:50%;transform:translateX(-50%);font-size:9px;color:var(--muted);white-space:nowrap}.analytics-panel{margin:20px 0;overflow:auto}.analytics-panel table{width:100%;border-collapse:collapse}.analytics-panel th,.analytics-panel td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}.analytics-filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.analytics-filters select{padding:10px;border:1px solid var(--line);border-radius:9px}@media(max-width:650px){.analytics-grid{grid-template-columns:1fr}.analytics-wrap{padding:0 14px}.analytics-card strong{font-size:27px}}</style></head><body class="dashboard"><main class="analytics-wrap"><a class="back-link" href="<?=e(base_url('admin/index.php'))?>">← Kembali ke dashboard</a><header class="admin-top" style="margin-top:20px"><div><div class="eyebrow">AUDIENCE / OVERVIEW</div><h1>Analytics<span class="lime">.</span></h1><p class="muted">Statistik agregat tanpa menyimpan alamat IP, cookie pelacakan, atau user-agent.</p></div><form class="analytics-filters"><label for="days">Rentang</label><select id="days" name="days" onchange="this.form.submit()"><option value="7" <?=$days===7?'selected':''?>>7 hari</option><option value="30" <?=$days===30?'selected':''?>>30 hari</option><option value="90" <?=$days===90?'selected':''?>>90 hari</option></select></form></header><section class="analytics-grid"><div class="analytics-card"><small>Page views (30 hari)</small><strong><?=number_format($total)?></strong><small>Beranda dan artikel</small></div><div class="analytics-card"><small>Article views (30 hari)</small><strong><?=number_format($articles)?></strong><small>Halaman artikel publik</small></div><div class="analytics-card"><small>Hari tercatat</small><strong><?=count($rows)?></strong><small>Hari dengan kunjungan</small></div></section><section class="analytics-panel"><h2>Tren kunjungan</h2><p class="muted">Total tampilan halaman per hari, rentang <?=$days?> hari.</p><div class="analytics-chart"><?php if(!$rows):?><p class="muted">Belum ada data. Kunjungan publik akan mulai tercatat setelah analytics aktif.</p><?php else: foreach($rows as $r): $height=max(3,(int)round(((int)$r['views']/$max)*130));?><div class="analytics-bar" style="height:<?=$height?>px" title="<?=e($r['day'])?>: <?= (int)$r['views']?> views"><span><?=e(date('d/m',strtotime($r['day'])))?></span></div><?php endforeach; endif;?></div><div style="height:28px"></div></section><section class="analytics-panel"><h2>Artikel populer</h2><p class="muted">Urutan berdasarkan tampilan artikel 30 hari terakhir.</p><table><thead><tr><th>Artikel</th><th>Views</th><th>Pratinjau</th></tr></thead><tbody><?php foreach($popular as $item):?><tr><td><?=e($item['title'])?></td><td><?=number_format((int)$item['views'])?></td><td><a target="_blank" rel="noopener" href="<?=e(base_url('article.php?slug='.rawurlencode($item['slug'])))?>">Buka ↗</a></td></tr><?php endforeach;?></tbody></table></section><p class="muted" style="font-size:12px">Catatan: statistik ini menghitung permintaan halaman, bukan pengunjung unik. Admin yang login tidak dihitung. Browser refresh dapat menambah hit.</p></main></body></html>
